/// <summary>Show the tag anchored to a world transform.</summary>
/// <param name="anchor">World transform to track (e.g. the interactable).</param>
/// <param name="worldOffset">Offset from the anchor's position (e.g. 1.5 units up).</param>
/// <param name="text">Prompt text to display.</param>
public void ShowAt(Transform anchor, Vector3 worldOffset, string text)
{
    _anchor = anchor;
    _anchorOffset = worldOffset;
    if (_label != null) _label.text = text;
    if (_root != null) _root.style.display = DisplayStyle.Flex;
    IsVisible = true;
    ApplyRootDisplay();
}

/// <summary>Hide the tag.</summary>
public void HideTag()
{
    _anchor = null;
    if (_root != null) _root.style.display = DisplayStyle.None;
    IsVisible = false;
    ApplyRootDisplay();
}

/// <summary>Keep the UIDocument root in sync with IsVisible so the inner element isn't hidden by a collapsed parent.</summary>
private void ApplyRootDisplay()
{
    if (Root != null)
        Root.style.display = IsVisible ? DisplayStyle.Flex : DisplayStyle.None;
}

