using UnityEngine;

/// <summary>
/// Drives the <see cref="InteractTagPanel"/> from the hover source. Reads
/// <see cref="PlayerMouseAimer.HoveredInteractable"/> each frame and positions the
/// panel at the interactable's world anchor with its prompt text. When nothing is
/// hovered the tag is hidden.
///
/// The tag is a pre-existing UIDocument under the UI manager, customisable via UXML/USS.
/// This presenter only shows/hides it and updates the anchor position and text.
/// </summary>
public class WorldInteractTagPresenter : MonoBehaviour
{
    [SerializeField] private PlayerMouseAimer _aimer;
    [SerializeField] private InteractTagPanel _tagPanel;

    private void Awake()
    {
        if (_aimer == null) _aimer = FindObjectOfType<PlayerMouseAimer>();
        if (_tagPanel == null) _tagPanel = FindObjectOfType<InteractTagPanel>();
    }

    private void LateUpdate()
    {
        if (_aimer == null || _tagPanel == null) return;

        IInteractionPromptProvider hovered = _aimer.HoveredInteractable;

        if (hovered != null && hovered.TryGetPrompt(out InteractionPrompt prompt) && prompt.IsValid)
        {
            Transform anchor = prompt.Anchor != null ? prompt.Anchor
                : hovered is Component c ? c.transform : null;

            if (anchor != null)
            {
                Vector3 offset = anchor.GetComponent<WorldInteractTag>()?.WorldOffset
                    ?? new Vector3(0f, 1.5f, 0f);
                _tagPanel.ShowAt(anchor, offset, prompt.Display);
            }
        }
        else
        {
            _tagPanel.HideTag();
        }
    }
}

